import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import './Resources.css';
import './ProductOverview.css'; // Ensure Nav styles are loaded

const ResourcesPage = () => {
  // --- TABS STATE ---
  const [activeTab, setActiveTab] = useState('overview');

  // --- NAVIGATION STATES ---
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const [isSolutionsMenuOpen, setIsSolutionsMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  
  // --- DATA ---
  const [brochures, setBrochures] = useState([]);
  const API_BASE_URL = 'https://aiiot-1.onrender.com';

  // --- FETCH BROCHURES ---
  useEffect(() => {
    const fetchBrochures = async () => {
      try {
        const response = await axios.get(`${API_BASE_URL}/api/brochures/`);
        // Filter for active brochures only
        const activeBrochures = response.data.filter(b => b.is_active);
        setBrochures(activeBrochures);
      } catch (error) {
        console.error('Error fetching brochures:', error);
      }
    };
    fetchBrochures();
  }, []);

  // --- NAV DATA ---
  const solutionsList = [
    { name: 'Air Quality Monitoring', link: '/project/intelligent-sensor' },
    { name: 'Flood Alert System', link: '/project/water-level' },
    { name: 'Digital Water Distribution', link: '/project/digital-water' },
    { name: 'Startup & Skill Development', link: '/project/startup-skill' }
  ];

  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'Indoor Monitor', image: '/sensor_modules/aqicrop.jpeg', link: '/product-details/indoor-monitor' },
        { name: 'Outdoor Station', image: '/sensor_modules/aqi1.jpeg', link: '/product-details/outdoor-station' },
        { name: 'Gas Sensors', image: 'https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=400', link: '/product-details/gas-sensors' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Smart Flood Alert System', image: '/sensor_modules/river1.jpg', link: '/product-details/flood-alert' },
        { name: 'Digital Flow Meter', image: '/sensor_modules/distribution.jpeg', link: '/product-details/distribution-net' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'AWS v1 & v2', image: '/sensor_modules/weather.jpg', link: '/product-details/weather-station' },
        { name: 'Rain Gauges', image: 'https://images.unsplash.com/photo-1590055531860-6902633df018?w=400', link: '/product-details/rain-gauge' }
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Workshops & Internships', image: '/sensor_modules/skill.jpg', link: '/product-details/iot-training' },
        { name: 'PCB Design Course', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/product-details/pcb-workshop' }
      ]
    }
  };

  return (
    <div className="resources-page-container">
      
      {/* 1. HEADER (Consistent with Website) */}
      <header className="aiiot-header-local">
         <div className="project-header-inner">
             <Link to="/" className="logo-link">
               <div className="logo-box">
                 <img src="/logo/logo.png" alt="Adi Shankara" style={{ height: '100%', width: 'auto' }} />
               </div>
               <div style={{ display: 'flex', flexDirection: 'column' }}>
                 <span style={{ fontSize: '1.1rem', fontWeight: 700, color: '#1e293b' }}>AI-IoT Innovations</span>
               </div>
             </Link>
 
             {/* DESKTOP NAV */}
             <div className="project-desktop-nav">
               <Link to="/" className="project-nav-link">Home</Link>
               
               <div className="dropdown-wrapper" onMouseEnter={() => setIsSolutionsMenuOpen(true)} onMouseLeave={() => setIsSolutionsMenuOpen(false)}>
                   <div className="project-nav-link product-trigger" style={{ cursor: 'pointer' }}>Solutions <span>▾</span></div>
                   <div className={`simple-dropdown ${isSolutionsMenuOpen ? 'visible' : ''}`}>
                     {solutionsList.map((sol, index) => (
                       <Link key={index} to={sol.link} className="simple-dropdown-item">{sol.name}</Link>
                     ))}
                   </div>
               </div>

               <div className="mega-menu-wrapper" onMouseEnter={() => setIsMegaMenuOpen(true)} onMouseLeave={() => setIsMegaMenuOpen(false)}>
                 <Link to="/products" className="project-nav-link product-trigger">Products <span>▾</span></Link>
                 <div className={`mega-menu-container ${isMegaMenuOpen ? 'visible' : ''}`}>
                   <div className="mega-menu-sidebar">
                     {Object.keys(productMenuData).map((key) => (
                       <div key={key} className={`mega-sidebar-item ${activeCategory === key ? 'active' : ''}`} onMouseEnter={() => setActiveCategory(key)}>
                         {key} <span>›</span>
                       </div>
                     ))}
                   </div>
                   <div className="mega-menu-content">
                     <div className="mega-content-header">
                       <h4>{productMenuData[activeCategory].title}</h4>
                       <p>{productMenuData[activeCategory].description}</p>
                     </div>
                     <div className="mega-grid">
                       {productMenuData[activeCategory].items.map((item, idx) => (
                         <Link to={item.link} key={idx} className="mega-product-card">
                            <div className="mega-img-box"><img src={item.image} alt={item.name} /></div>
                            <span>{item.name}</span>
                         </Link>
                       ))}
                     </div>
                   </div>
                 </div>
               </div>
               
               <Link to="/resources" className="project-nav-link" style={{color:'#3b82f6'}}>R&D</Link>
               <a href="#contact" className="btn-primary-small">Get in Touch</a>
             </div>
 
             {/* MOBILE TOGGLE */}
             <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
               {isMobileMenuOpen ? '✕' : '☰'}
             </button>
         </div>

         {/* MOBILE MENU */}
         {isMobileMenuOpen && (
            <div className="mobile-menu-wrapper">
                <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">Home</Link>
                <Link to="/resources" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">R&D Center</Link>
                <a href="#contact" className="btn-primary" style={{ textAlign: 'center', marginTop: '1rem' }}>Contact</a>
            </div>
         )}
      </header>

      {/* 2. MAIN CONTENT */}
      <div className="resources-content-wrapper">
        
        {/* Hero */}
        <section className="resources-hero-section">
          <h1 className="page-title">Center for AI-IoT Innovation</h1>
          <p className="page-subtitle">Bridging the gap between academic research and industrial application through advanced Environmental Intelligence.</p>
          
          {/* TABS Navigation */}
          <div className="tabs-container">
            <button className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => setActiveTab('overview')}>Overview</button>
            <button className={`tab-btn ${activeTab === 'areas' ? 'active' : ''}`} onClick={() => setActiveTab('areas')}>Research Areas</button>
            <button className={`tab-btn ${activeTab === 'output' ? 'active' : ''}`} onClick={() => setActiveTab('output')}>Publications & Patents</button>
            <button className={`tab-btn ${activeTab === 'downloads' ? 'active' : ''}`} onClick={() => setActiveTab('downloads')}>Downloads</button>
          </div>
        </section>

        {/* --- TAB 1: OVERVIEW (Your existing Objective Content) --- */}
        {activeTab === 'overview' && (
            <div className="objectives-card green-accent">
                <h3 className="section-headline">🚀 Our Core Objectives</h3>
                <p className="highlight-box">
                Main Objective: Development of digital networking for preventive and predictive environmental and climatic warning solutions.
                </p>
                <ul className="custom-list">
                <li>Develop intelligent sensor modules for pollution monitoring.</li>
                <li>Validate smart water level monitoring with flood alerts.</li>
                <li>Create digital systems for water level distribution.</li>
                <li>Build a startup & skill development ecosystem.</li>
                <li>Develop Explainable AI (XAI) analysis software for IoT.</li>
                </ul>
            </div>
        )}

        {/* --- TAB 2: RESEARCH AREAS (New R&D Content) --- */}
        {activeTab === 'areas' && (
            <div className="resources-grid">
                <div className="resource-card">
                    <span className="card-icon">🧠</span>
                    <h4 className="card-title">Explainable AI (XAI)</h4>
                    <p className="card-desc">Developing interpretable machine learning models for environmental forecasting, ensuring AI decisions are transparent and trusted.</p>
                </div>
                <div className="resource-card">
                    <span className="card-icon">📡</span>
                    <h4 className="card-title">IoT & Edge Computing</h4>
                    <p className="card-desc">Designing ultra-low power LoRaWAN nodes capable of processing data at the edge for real-time alerts in remote areas.</p>
                </div>
                <div className="resource-card">
                    <span className="card-icon">🌊</span>
                    <h4 className="card-title">Hydro-Informatics</h4>
                    <p className="card-desc">Utilizing LSTM neural networks to model river basins and predict flood risks up to 6 hours in advance.</p>
                </div>
                <div className="resource-card">
                    <span className="card-icon">🏭</span>
                    <h4 className="card-title">Industrial Safety</h4>
                    <p className="card-desc">High-precision detection of hazardous gas leaks (Ammonia, Chlorine) using specialized electrochemical sensor arrays.</p>
                </div>
            </div>
        )}

        {/* --- TAB 3: OUTPUT (Publications & Patents) --- */}
        {activeTab === 'output' && (
            <div>
                <div className="objectives-card blue-accent">
                    <h3 className="section-headline">📜 Intellectual Property</h3>
                    <p style={{fontSize:'1.1rem', color:'#475569', marginBottom:'0.5rem'}}><strong>Patent Filed:</strong> Intelligent Water Level Monitoring & Alert System</p>
                    <p style={{fontSize:'0.9rem', color:'#64748b'}}>Status: Pending Examination (Application No: 2024410XXXX)</p>
                </div>

                <h3 className="section-headline" style={{marginTop:'3rem', paddingLeft:'1rem', borderLeft:'5px solid #3b82f6'}}>Selected Publications</h3>
                <div className="resources-grid">
                    <div className="resource-card">
                        <h4 className="card-title">River Level Forecasting using LSTM</h4>
                        <p className="card-desc">Published in IEEE Access, 2024. A study on deep learning models for the Periyar river basin.</p>
                        <span className="action-btn">Read Paper ↗</span>
                    </div>
                    <div className="resource-card">
                        <h4 className="card-title">Low-Power LoRaWAN Nodes</h4>
                        <p className="card-desc">Presented at ICSS 2023. Optimizing battery life for remote air quality monitoring stations.</p>
                        <span className="action-btn">Read Paper ↗</span>
                    </div>
                </div>
            </div>
        )}

        {/* --- TAB 4: DOWNLOADS (Dynamic Brochures) --- */}
        {activeTab === 'downloads' && (
            <div>
                {brochures.length === 0 ? (
                    <p style={{textAlign:'center', color:'#64748b'}}>Loading resources or no documents available...</p>
                ) : (
                    <div className="resources-grid">
                    {brochures.map((b, idx) => (
                        <div key={idx} className="resource-card">
                        <div>
                            <span style={{background:'#eff6ff', color:'#3b82f6', padding:'0.2rem 0.8rem', borderRadius:'1rem', fontSize:'0.75rem', fontWeight:'bold', textTransform:'uppercase'}}>{b.category}</span>
                            <h4 className="card-title" style={{marginTop:'1rem'}}>{b.title}</h4>
                            <p className="card-desc">{b.description}</p>
                        </div>
                        <a href={b.file.startsWith('http') ? b.file : `${API_BASE_URL}${b.file}`} target="_blank" rel="noopener noreferrer" className="action-btn">
                            <span>📥</span> Download PDF
                        </a>
                        </div>
                    ))}
                    </div>
                )}
            </div>
        )}

        <div className="back-link-wrapper">
          <Link to="/" className="back-link">← Back to Home</Link>
        </div>
      </div>
    </div>
  );
};

export default ResourcesPage;
